import { describe, expect, it } from "vitest";
import { mapBoardToColumns } from "@/lib/onboarding/mappers";
import type { BoardDTO, OnboardingDTO } from "@/lib/onboarding/types";

function makeOnboarding(overrides: Partial<OnboardingDTO> = {}): OnboardingDTO {
  return {
    id: "ob-1", user_id: "u-1",
    client_name: "Jane Doe", email: "jane@example.com", assigned_rm: "Alice RM",
    client_ref: "MEGA-0481",
    primary_phone: "+852 1234 5678", address: "1 Main St", country_of_residence: "HK",
    id_type: "passport", id_number: "P123456",
    ibhk_account: "U-1000001", sw_account: "SW-2000001",
    status: "initial", kind: "initial",
    model_id: "m-1", model_name: "Zero", units: 5,
    mgmt_fee: 0.015, incentive_fee: 0.2,
    verified_count: 3, required_count: 7,
    reject_reason: null, awaiting_reprovision: false,
    submitted_at: null, created_at: "2026-07-18T00:00:00Z",
    documents: [],
    ...overrides,
  };
}

describe("FE-3 mapBoardToColumns", () => {
  it("produces 4 columns matching the §4.2 status→column labels, one client per bucket", () => {
    const board: BoardDTO = {
      initial: [makeOnboarding({ status: "initial" })],
      reviewing: [makeOnboarding({ id: "ob-2", status: "reviewing" })],
      pending_review: [makeOnboarding({ id: "ob-3", status: "pending_review" })],
      active: [makeOnboarding({ id: "ob-4", status: "active" })],
    };
    const columns = mapBoardToColumns(board);
    // Column order follows COLUMN_LABELS' own key insertion order (mappers.ts:14-19,
    // iterated via Object.keys in mapBoardToColumns): initial, pending_review,
    // reviewing, active — not initial/reviewing/pending_review/active.
    expect(columns.map((c) => c.label)).toEqual([
      "Initial Onboarding", "Pending for Resubmit", "Reviewing", "Active",
    ]);
    expect(columns.map((c) => c.status)).toEqual(["initial", "pending_review", "reviewing", "active"]);
    columns.forEach((c) => expect(c.clients).toHaveLength(1));
  });

  it("mapRow passes phone/address/country/idType/idNumber/ibhkAccount/swAccount/clientRef straight through — no '—' fallback (D-9)", () => {
    const board: BoardDTO = {
      initial: [makeOnboarding()], reviewing: [], pending_review: [], active: [],
    };
    const [client] = mapBoardToColumns(board)[0].clients;
    expect(client.phone).toBe("+852 1234 5678");
    expect(client.address).toBe("1 Main St");
    expect(client.country).toBe("HK");
    expect(client.idType).toBe("passport");
    expect(client.idNumber).toBe("P123456");
    expect(client.ibhkAccount).toBe("U-1000001");
    expect(client.swAccount).toBe("SW-2000001");
    expect(client.clientRef).toBe("MEGA-0481");
    expect(client.verifiedCount).toBe(3);
    expect(client.requiredCount).toBe(7);
  });

  it("produces empty column arrays when a bucket is empty (no crash on 0 clients)", () => {
    const board: BoardDTO = { initial: [], reviewing: [], pending_review: [], active: [] };
    const columns = mapBoardToColumns(board);
    columns.forEach((c) => expect(c.clients).toEqual([]));
  });
});
